import os,json,urllib.request
url='https://usegalaxy.org/api/tools/toolshed.g2.bx.psu.edu%2Frepos%2Fiuc%2Frgrnastar%2Frna_star%2F2.7.11b%2Bgalaxy1?io_details=true'
