req=urllib.request.Request(url,headers={'x-api-key':key})
data=json.load(urllib.request.urlopen(req))

def find_genomes(x):
    if isinstance(x,dict):
        if x.get('name')=='genomeDir':
            opts=x.get('options') or []
            hits=[o for o in opts if any(s.lower() in (o[0]+' '+o[1]).lower() for s in ['hg38','hg19','grch38','grch37','human'])]
            print('genomeDir options containing human/hg/grch:', len(hits))
            for o in hits[:100]: print(o[1], '|', o[0])
            print('first 100 labels maybe:')
            for o in opts[:100]: print(o[1], '|', o[0])
        for k,v in x.items(): find_genomes(v)
    elif isinstance(x,list):
        for v in x: find_genomes(v)
find_genomes(data)
